// Helper functions
export function getAllTeams(): AMS2RealTeam[] {
  return AMS2_CAR_CLASSES.flatMap(c => c.teams);
}

export function getTeamById(id: string): AMS2RealTeam | undefined {
  return getAllTeams().find(t => t.id === id);
}

export function getTeamsForClass(classId: string): AMS2RealTeam[] {
  const carClass = AMS2_CAR_CLASSES.find(c => c.id === classId);
  return carClass?.teams ?? [];
}

export function getTeamsByTier(tier: TeamTier): AMS2RealTeam[] {
  return getAllTeams().filter(t => t.tier === tier);
}

export function getTeamsForReputation(reputation: number): AMS2RealTeam[] {
  return getAllTeams().filter(t => t.reputationRequired <= reputation);
}

export function getCarClassById(classId: string): AMS2CarClass | undefined {
  return AMS2_CAR_CLASSES.find(c => c.id === classId);
}

export function getModernCarClasses(): AMS2CarClass[] {
  return AMS2_CAR_CLASSES.filter(c => c.isModern);
}

// Lightweight manufacturer detection (keyword-based)
const MANUFACTURER_KEYWORDS: Array<{ keyword: RegExp; id: string }> = [
  { keyword: /bmw/i, id: 'bmw' },
  { keyword: /porsche/i, id: 'porsche' },
  { keyword: /mercedes|amg/i, id: 'mercedes-amg' },
  { keyword: /audi/i, id: 'audi' },
  { keyword: /lamborghini|lambo/i, id: 'lamborghini' },
  { keyword: /cadillac/i, id: 'cadillac' },
  { keyword: /mclaren/i, id: 'mclaren' },
  { keyword: /aston|amr/i, id: 'aston-martin' },
  { keyword: /ferrari/i, id: 'ferrari' },
  { keyword: /corvette/i, id: 'corvette' },
  { keyword: /chevrolet|chevy/i, id: 'chevrolet' },
  { keyword: /nissan/i, id: 'nissan' },
  { keyword: /alpine/i, id: 'alpine' },
  { keyword: /peugeot/i, id: 'peugeot' },
  { keyword: /acura/i, id: 'acura' },
  { keyword: /honda/i, id: 'honda' },
  { keyword: /toyota/i, id: 'toyota' },
  { keyword: /ford/i, id: 'ford' },
  { keyword: /ginetta/i, id: 'ginetta' },
  { keyword: /camaro/i, id: 'camaro' },
  { keyword: /lancia/i, id: 'lancia' },
  { keyword: /volkswagen|vw/i, id: 'volkswagen' },
  { keyword: /hyundai/i, id: 'hyundai' },
];

export function detectManufacturerId(teamName: string): string | undefined {
  for (const { keyword, id } of MANUFACTURER_KEYWORDS) {
    if (keyword.test(teamName)) return id;
  }
  return undefined;
}

export function detectProgramType(teamName: string): 'works' | 'customer' | 'spec-series' {
  const manu = detectManufacturerId(teamName);
  if (!manu) return 'customer';
  // Heuristic: if name contains "Motorsport", "Works", "Factory", treat as works
  if (/\b(motorsport|works|factory|team)\b/i.test(teamName)) return 'works';
  return 'customer';
}

export function getTeamsByManufacturer(manufacturerId: string): AMS2RealTeam[] {
  return getAllTeams().filter(t => 
    (t as any).manufacturerId === manufacturerId || detectManufacturerId(t.name) === manufacturerId
  );
}

export function findRelatedTeamEntries(teamId: string): AMS2RealTeam[] {
  const team = getTeamById(teamId);
  if (!team) return [];
  const manu = (team as any).manufacturerId || detectManufacturerId(team.name);
  if (manu) {
    return getTeamsByManufacturer(manu).filter(t => t.id !== team.id && t.carClassId === team.carClassId);
  }
  // Fallback: same car class and similar name prefix
  return getTeamsForClass(team.carClassId).filter(t => t.id !== team.id && t.name.split(' ')[0] === team.name.split(' ')[0]);
}

export function getCarNameForManufacturer(carClassId: string, manufacturerId?: string): string {
  const classObj = getCarClassById(carClassId);
  if (!classObj) return manufacturerId ? `${manufacturerId.toUpperCase()} ${carClassId}` : carClassId;
  if (manufacturerId) {
    const manuUpper = manufacturerId.toUpperCase();
    return `${manuUpper} ${classObj.name}`;
  }
  return classObj.name;
}

